package vn.covie.catalog.model;
import jakarta.persistence.*;
@Entity @Table(name="variant_option_values") public class VariantOptionValueEntity { @EmbeddedId private VariantOptionValueId id; @MapsId("variantId") @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="variant_id",nullable=false) private VariantEntity variant; @MapsId("optionValueId") @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="option_value_id",nullable=false) private OptionValueEntity optionValue; protected VariantOptionValueEntity(){} public static VariantOptionValueEntity associate(VariantEntity variant,OptionValueEntity optionValue){VariantOptionValueEntity association=new VariantOptionValueEntity();association.id=new VariantOptionValueId(variant.getId(),optionValue.getId());association.variant=variant;association.optionValue=optionValue;return association;} public VariantOptionValueId getId(){return id;} }
